def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([5]), fmt([-7]), fmt([2, 2]), fmt([1, 2]), fmt([2, 1]), fmt([-3, -3, 4, 4]), fmt([4, -1, 4, 9, -1, 4, 9]), fmt([8, 3, 8, 3, 5, 1])]
    for n in (4, 6, 9, 12, 20, 30):
        for _ in range(2):
            tests.append(fmt([rng.randint(-4, 4) for _ in range(n)]))
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(30)]))
    N = 200000
    tests.append(fmt([rng.randint(1, 10) for _ in range(N)]))
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(N)]))
    tests.append(fmt([rng.randint(-1000, 1000) for _ in range(N)]))
    tests.append(fmt([10**9] * (N // 2) + [-10**9] * (N // 2)))
    return tests

